mapper.select:
SELECT cf.resource_id AS customerId, cf.field_id AS fieldId
FROM customer_field cf
JOIN customer c ON c.id = cf.resource_id
WHERE c.organization_id = #{orgId}
  AND cf.resource_id IN
  #{cid}
  AND cf.field_id IN
  #{fid}
  AND cf.field_value IS NOT NULL AND cf.field_value != ''
UNION
SELECT b.resource_id AS customerId, b.field_id AS fieldId
FROM customer_field_blob b
JOIN customer c ON c.id = b.resource_id
WHERE c.organization_id = #{orgId}
  AND b.resource_id IN
  #{cid}
  AND b.field_id IN
  #{fid}
  AND b.field_value IS NOT NULL AND b.field_value != ''
